Misère Nim follows normal Nim unless all heaps size 1 or exactly one heap >1; in the latter, adjust move to leave an odd count of heaps of size 1 for opponent, ensuring misère optimality. This special handling prevents losing positions after forcing all heaps to size 1.

```python
def misere_nim_move(piles):
    nonzero = [i for i, p in enumerate(piles) if p > 0]
    if not nonzero:
        return "0,0"  # no move possible

    # Counts
    ones = sum(1 for p in piles if p == 1)
    gt1_indices = [i for i, p in enumerate(piles) if p > 1]

    # Case 1: all piles size 1
    if len(gt1_indices) == 0:
        i = nonzero[0]
        # Take 1 from any pile; leaving even number of ones is favorable
        return f"{i},1"

    # Case 2: exactly one pile >1
    if len(gt1_indices) == 1:
        i = gt1_indices[0]
        pile_size = piles[i]
        m = ones  # count of ones

        if m % 2 == 0:
            # leave 1 in this pile: take pile_size - 1
            take = pile_size - 1
        else:
            # remove entire pile: take pile_size
            take = pile_size
        return f"{i},{take}"

    # Case 3: more than one pile >1 - normal Nim
    xor = 0
    for p in piles:
        xor ^= p

    if xor == 0:
        # losing, remove 1 from first nonzero heap
        i = nonzero[0]
        return f"{i},1"

    for i, p in enumerate(piles):
        target = p ^ xor
        if target < p:
            take = p - target
            return f"{i},{take}"

    # Fallback: remove 1 from first nonzero heap
    i = nonzero[0]
    return f"{i},1"
